-- PCO: logo oficial do site, CNPJ do diretório nacional (tabela TSE) e
-- respostas do diagnóstico apenas onde a observação pública sustenta a nota.
-- Não designa DPO. Encarregado do programa permanece vazio.

UPDATE public.empresa
SET cnpj = 1307059000190
WHERE razao_social = 'PARTIDO DA CAUSA OPERÁRIA (PCO)';

UPDATE public.programa
SET
  cnpj = 1307059000190,
  logo_orgao_empresa = $logo$data:image/png;base64,$logo$,
  logo_programa = $logo$data:image/png;base64,$logo$
WHERE slug = 'pco-diagnostico';

UPDATE public.registro_ropa rr
SET
  cnpj = '01.307.059/0001-90',
  observacoes = rr.observacoes || E'\n\nCNPJ do diretório nacional: 01.307.059/0001-90, publicado pelo TSE na tabela de contas bancárias dos diretórios nacionais (prestação de contas do exercício de 2015). A página https://pco.org.br/institucional/ existe e, em 19/11/2026, não trazia CNPJ nem corpo de texto. O CNPJ 12.197.071/0001-05 de agregador cadastral continua sendo outro órgão (direção regional em São Paulo), não este número nacional. Vigência cadastral atual do 01.307.059/0001-90: conferir na Receita, a tabela do TSE é de 2015.'
FROM public.programa p
WHERE rr.programa_id = p.id AND p.slug = 'pco-diagnostico'
  AND rr.observacoes NOT LIKE '%01.307.059/0001-90%';

DO $$
DECLARE
  pid integer;
  nota text := 'Observação pública em 19/11/2026. A nota descreve o que foi visto ou o que este diagnóstico já registrou. Não é decisão do partido nem declaração de irregularidade. O que não foi respondido permanece em aberto porque não havia evidência suficiente.';
BEGIN
  SELECT id INTO pid FROM public.programa WHERE slug = 'pco-diagnostico';
  IF pid IS NULL THEN
    RAISE EXCEPTION 'Programa pco-diagnostico não encontrado';
  END IF;

  INSERT INTO public.programa_controle (controle, programa, nivel)
  SELECT c.id, pid, NULL FROM public.controle c
  WHERE NOT EXISTS (
    SELECT 1 FROM public.programa_controle pc
    WHERE pc.programa = pid AND pc.controle = c.id
  );

  INSERT INTO public.programa_medida (programa, medida, controle, resposta, prioridade)
  SELECT pid, m.id, m.id_controle, NULL, false
  FROM public.medida m
  WHERE NOT EXISTS (
    SELECT 1 FROM public.programa_medida pm
    WHERE pm.programa = pid AND pm.medida = m.id
  );

  CREATE TEMP TABLE _pco_diag (
    id_medida text PRIMARY KEY,
    resposta int NOT NULL,
    justificativa text NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO _pco_diag (id_medida, resposta, justificativa) VALUES
    ('0.12', 1, $j$Sim. Há página publicada em https://pco.org.br/politica-de-privacidade/. O texto é o modelo padrão do WordPress (comentários, Gravatar, cookies de login, mídia e antispam). Não descreve a filiação nem o encarregado. A resposta Sim é só sobre a existência da página, não sobre a qualidade.$j$),
    ('0.4', 2, $j$Não, no que se pode ver em público. Nas páginas /, /filiar/, /politica-de-privacidade/, /contato/ e /institucional/ não há identificação de encarregado da LGPD. Em /como-funciona-o-pco/ a palavra encarregado designa o presidente para decisões urgentes entre reuniões da Comissão Executiva. Isso não é o encarregado do art. 41. Não se afirma que não exista designação interna. O dono deste programa no FPSI não foi nomeado DPO do partido, e o campo encarregado ficou vazio para o portal não publicar um nome.$j$);

  -- 0.4 acima foi inserido como 2 por engano de rascunho; a resposta correta é não responder.
  DELETE FROM _pco_diag WHERE id_medida = '0.4';

  INSERT INTO _pco_diag (id_medida, resposta, justificativa) VALUES
    ('19.1', 3, $j$Registro inicial da filiação está no ROPA deste diagnóstico, montado a partir do formulário público. Não é ainda o processo operacional do partido. Falta a validação interna.$j$),
    ('19.2', 3, $j$A jornada do titular foi modelada (visita, formulário, envio, e-mail, cadastro, uso, compartilhamento, manutenção, direitos, retenção). Vários elos estão como hipótese ou A VALIDAR.$j$),
    ('19.3', 3, $j$O ROPA lista agentes e compartilhamentos possíveis (e-mail, WhatsApp, hospedagem, Turnstile, Justiça Eleitoral, diretórios). Nenhum fluxo foi confirmado pelo partido. Transferência internacional ficou A VALIDAR.$j$),
    ('19.4', 3, $j$O inventário separa dado pessoal, sensível (a filiação), cadastral, eleitoral, contato, financeiro e o que exige avaliação de necessidade. Categorias de titulares: quem pede filiação, visitante e contato do site.$j$),
    ('20.1', 3, $j$O fluxo de incidente está descrito no programa (identificação até lições aprendidas), como processo proposto. Não há evidência de que o partido já opere esse processo. Nenhum incidente foi lançado.$j$),
    ('21.2', 3, $j$Há meios públicos de contato (formulário em /contato/, e-mail sorg@sorg.pco.org.br na ficha do TSE e telefone no formulário de filiação). Nenhum deles se apresenta como canal do encarregado ou do art. 18. O portal deste diagnóstico existe e não está divulgado no site do partido.$j$),
    ('21.3', 3, $j$O processo de direitos (confirmação, acesso, correção, eliminação quando couber, informação e oposição) está desenhado neste FPSI e ainda não opera como canal do partido.$j$),
    ('21.4', 5, $j$A medida pede divulgação pública da identidade e do contato do encarregado. Nas páginas consultadas isso não aparece. Não se conclui que não haja nomeação interna. O campo de encarregado deste programa ficou vazio de propósito.$j$),
    ('23.1', 6, $j$Não se aplica nos termos da medida. O texto é de órgão público (finalidade pública e competência legal). O PCO é partido político, pessoa jurídica de direito privado. A base legal da filiação continua A VALIDAR.$j$),
    ('23.3', 3, $j$Há RIPD em rascunho da filiação pelo site, pelo dado sensível e pelos identificadores eleitorais. Sem parecer de encarregado e sem decisão do controlador.$j$),
    ('23.4', 6, $j$Não se aplica. Não há tratamento de estudo em saúde pública no recorte observado (site e filiação).$j$),
    ('24.2', 6, $j$Não se aplica nos termos da medida, escrita para compartilhamento entre órgãos e entidades públicos. Um eventual registro de filiação na Justiça Eleitoral é hipótese jurídica, não esse fluxo.$j$),
    ('24.3', 6, $j$Não se aplica nos termos da medida. O dever de comunicar a ANPD o compartilhamento com pessoa jurídica de direito privado, nessa redação, é de órgão público.$j$),
    ('25.1', 3, $j$A política publicada informa finalidades de comentário, conta e mídia. O formulário de filiação não informa a finalidade do pedido, da contribuição nem do WhatsApp.$j$),
    ('25.2', 3, $j$Não há texto, no ponto de coleta da filiação, que limite o uso à finalidade informada. A política do site cobre outro tratamento (comentários). Compatibilidade da filiação: A VALIDAR.$j$),
    ('25.6', 3, $j$Informação pública existe, mas não é clara para quem se filia: a política é o modelo do WordPress e o HTML de /filiar/ não menciona privacidade, direitos ou encarregado.$j$),
    ('25.7', 3, $j$No site público: HTTPS e Cloudflare Turnstile no formulário. Acesso, criptografia em repouso, backup, logs e descarte não foram verificados.$j$),
    ('25.10', 3, $j$Este diagnóstico é o início do registro de prestação de contas (ROPA, riscos, plano, evidências com link). Ainda não é um programa de responsabilização adotado pelo partido.$j$),
    ('1.1', 3, $j$Inventário inicial dos sistemas vistos no site (WordPress, formulários, banco hipotético, e-mail, hospedagem, DNS, Turnstile, fontes, analytics, portal eleitoral, WhatsApp). Não cobre o parque do partido.$j$),
    ('2.1', 3, $j$Inventário de software do site a partir do HTML: WordPress (meta generator 7.1.5), Elementor, JetFormBuilder, JetEngine, Independent Analytics, Fluent Forms. Ambiente interno A VALIDAR.$j$),
    ('3.1', 3, $j$A gestão de dados da filiação começou neste diagnóstico (inventário, ROPA e jornada). Não há processo institucional confirmado.$j$),
    ('3.2', 3, $j$Inventário dos dados do formulário de filiação e do contato do site. Demais operações do partido A VALIDAR.$j$),
    ('3.10', 3, $j$O site e o formulário de filiação respondem em HTTPS. Criptografia do restante do ambiente, inclusive e-mail e banco, A VALIDAR.$j$),
    ('15.1', 3, $j$Mapa inicial de terceiros: Hetzner e LiteSpeed pelo IP e pelo cabeçalho, Cloudflare no DNS e no Turnstile, Google Fonts, plugins, e-mail e pagamento ainda sem nome. Contratos não vistos.$j$),
    ('15.3', 3, $j$Os fornecedores observados foram classificados por criticidade (hospedagem e formulário mais altos). A avaliação de cada um segue pendente.$j$),
    ('16.4', 3, $j$Componentes de terceiros visíveis no HTML do site foram listados. Não há inventário gerido pelo partido nem política de atualização confirmada.$j$);

  UPDATE public.programa_medida pm
  SET
    resposta = d.resposta::text,
    justificativa = d.justificativa,
    observacao_orgao = nota
  FROM public.medida m
  JOIN _pco_diag d ON d.id_medida = m.id_medida
  WHERE pm.programa = pid AND pm.medida = m.id;

  -- 0.4 fica sem nota, com o esclarecimento de que o dono do FPSI não é o DPO.
  UPDATE public.programa_medida pm
  SET
    resposta = NULL,
    justificativa = $j$Não respondida. Não localizamos publicamente o encarregado da LGPD, e isso não prova que não haja nomeação interna. Em /como-funciona-o-pco/ a palavra encarregado é o presidente para decisões urgentes da Comissão Executiva, não o art. 41. Jorge Psendziuk (jimxxx@gmail.com) é o dono deste diagnóstico no FPSI e não foi nomeado DPO do partido.$j$,
    observacao_orgao = nota
  FROM public.medida m
  WHERE pm.programa = pid AND pm.medida = m.id AND m.id_medida = '0.4';
END $$;
